# Frozen Duck Core engine v4_0: generated by tools/freeze_engine.py from 79cc25d:src/duckmind/expression_sweep/envelope.py; do not edit.
"""Sweep results → the largest amplitude each clip may use, per posture.

A variant passes when, over every randomized episode that had settled into its posture
when the clip began, the duck never fell, the trunk never tipped far from how it had
settled, the head servos stayed under the torque budget and the head never hit the
body. Episodes that had not settled (the duck already leaning when the clip began) are
counted apart as ``settle_failures``: they describe the posture, not the clip. A clip's
cap is the largest swept amplitude at which every tempo and both sides pass. Tracking
fidelity is reported but does not gate safety: a clip the network only half-performs is
safe, just less expressive.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from duckmind.engines.v4_0.duckcore import content
from duckmind.engines.v4_0.expression_sweep import looks
from duckmind.engines.v4_0.expression_sweep.clips import AMPLITUDES, SIDES, TEMPOS, clip_digest

# 2: safety measured from the settled moment on, relative to the settled trunk; format 1
# counted the drop into the posture after reset against every clip.
# 3: adds the looks, the sit ↔ stand cycle counted per phase by robotd's own fall rule with
# self-righting, head-offset walks, and a raw per-episode ``.trials.jsonl`` beside the
# result. The per-variant head statistics keep their format-2 meaning (plus new keys), so
# format-2 results and the caps made from them stay readable and valid.
RESULT_FORMAT = 3
READABLE_RESULT_FORMATS = (2, 3)
CAPS_FORMAT = 1
POSTURES = ("sit", "stand")


@dataclass(frozen=True)
class Criteria:
    """What makes a variant safe.

    Load is judged by how long the head servos strain (time above the stall-penalty load
    the walking policy was trained with), not by the single largest instant: the first
    sweep's standing failures were one-tick spikes in one episode of 32 while sustained
    strain stayed at zero, and failing on those silenced most standing expressions. The
    soft jaw may brush the body in at most one randomized episode.
    """

    max_falls: int = 0
    max_tilt_rise_deg: float = 20.0  # 95th percentile of the trunk's largest tip from settled
    max_strain_frac: float = 0.05  # 95th percentile of the time the head servos strain
    max_self_contacts: int = 1  # randomized episodes in which the jaw touched the trunk


def load(path: Path) -> dict[str, Any]:
    result = json.loads(path.read_text())
    if result.get("format") not in READABLE_RESULT_FORMATS:
        raise ValueError(f"unsupported sweep result format {result.get('format')!r}")
    return result


def is_current(result: dict[str, Any]) -> bool:
    """Whether the sweep ran on today's whole content table (informational)."""
    return result.get("source", {}).get("content_table") == content.table_hash()


def current_clips(result: dict[str, Any]) -> set[str]:
    """Clips whose swept commands are identical to today's; only their caps count."""
    digests = result.get("source", {}).get("clip_digests", {})
    return {
        clip
        for clip, digest in digests.items()
        if clip in content.CLIPS and clip_digest(clip) == digest
    }


def passes(stats: dict[str, Any], criteria: Criteria) -> bool:
    return (
        stats["falls"] <= criteria.max_falls
        and stats["tilt_rise_deg_p95"] <= criteria.max_tilt_rise_deg
        and stats.get("strain_frac_p95", 0.0) <= criteria.max_strain_frac
        and stats["self_contacts"] <= criteria.max_self_contacts
    )


def caps(result: dict[str, Any], criteria: Criteria | None = None) -> dict[str, dict[str, float]]:
    """{clip: {posture: largest passing amplitude, 0.0 if none}} over the swept grid."""
    criteria = criteria or Criteria()
    by_key = result["variants"]
    out: dict[str, dict[str, float]] = {}
    for clip in sorted({key.split("@", 1)[0] for key in by_key}):
        out[clip] = {}
        for posture in POSTURES:
            best = 0.0
            for amplitude in AMPLITUDES:
                keys = [
                    f"{clip}@a{amplitude:g}/t{tempo:g}/{'L' if side > 0 else 'R'}"
                    for tempo in TEMPOS
                    for side in SIDES
                ]
                runs = [by_key[key].get(posture) for key in keys if key in by_key]
                if len(runs) != len(keys) or any(run is None for run in runs):
                    break  # not swept at this amplitude: do not extrapolate
                if not all(passes(run, criteria) for run in runs if run is not None):
                    break  # amplitudes are nested: a failure caps everything above it
                best = amplitude
            out[clip][posture] = best
    return out


def look_caps(
    result: dict[str, Any], criteria: Criteria | None = None
) -> dict[str, dict[str, float]]:
    """The same caps for the sweep-only looks (information: Duck Core never loads these)."""
    swept = {
        key: entry
        for key, entry in result.get("looks", {}).items()
        if key.split("@", 1)[0] != looks.CONTROL
    }
    return caps({"variants": swept}, criteria)


def fidelity(result: dict[str, Any], clip: str, posture: str) -> float | None:
    """Mean fraction of the commanded head motion the network actually performed."""
    ratios = [
        stats["track_ratio"]
        for key, entry in result["variants"].items()
        if key.startswith(f"{clip}@") and (stats := entry.get(posture)) is not None
    ]
    return sum(ratios) / len(ratios) if ratios else None


def settle_failures(result: dict[str, Any], posture: str) -> tuple[int, int]:
    """(episodes not settled when their clip began, all episodes) for one posture."""
    runs = [entry[posture] for entry in result["variants"].values() if posture in entry]
    return (
        sum(run.get("settle_failures", 0) for run in runs),
        sum(run["episodes"] for run in runs),
    )


def engine_caps(capped: dict[str, dict[str, float]]) -> dict[str, int]:
    """Fixed-point caps for :class:`~duckmind.duckcore.engine.DuckCore`.

    ``clip@sit`` and ``clip@stand`` apply in that posture; the bare ``clip`` (the stricter
    of the two) is for a reader that does not know the posture.
    """
    out: dict[str, int] = {}
    for clip, by_posture in capped.items():
        out[clip] = round(min(by_posture.values()) * 10_000)
        for posture, value in by_posture.items():
            out[f"{clip}@{posture}"] = round(value * 10_000)
    return out


def write_caps(
    result: dict[str, Any], path: Path, criteria: Criteria | None = None
) -> dict[str, Any]:
    """Distil a sweep result into the small file the simulator and robot load.

    Only clips unchanged since the sweep are written; edited or new clips stay at the
    conservative cap until they are swept.
    """
    valid = current_clips(result)
    if not valid:
        raise ValueError("no swept clip matches today's clips; run the sweep again")
    capped = {clip: value for clip, value in caps(result, criteria).items() if clip in valid}
    payload = {
        "format": CAPS_FORMAT,
        "result_format": result.get("format"),
        "content_table": content.table_hash(),
        "clip_digests": {clip: clip_digest(clip) for clip in sorted(capped)},
        "source": {
            key: value for key, value in result.get("source", {}).items() if key != "clip_digests"
        },
        "caps": capped,
        "engine": engine_caps(capped),
        "motion": result.get("motion", {}),
    }
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
    return payload


def read_caps(path: Path) -> dict[str, int] | None:
    """Engine caps from a caps file, or None when missing or made for other clips."""
    if not path.is_file():
        return None
    payload = json.loads(path.read_text())
    if (
        payload.get("format") != CAPS_FORMAT
        or payload.get("result_format") not in READABLE_RESULT_FORMATS
    ):
        return None  # made by an older sweep whose measurements no longer count
    digests = payload.get("clip_digests", {})
    kept = {
        str(key): int(value)
        for key, value in payload["engine"].items()
        if (clip := str(key).split("@", 1)[0]) in content.CLIPS
        and digests.get(clip) == clip_digest(clip)
    }
    return kept or None
